let data, filter='all', saved={}, storageOK=true;
try{saved=JSON.parse(localStorage.getItem('math285-progress-v1')||'{}')}catch{storageOK=false}
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
const allProblems=()=>Object.values(data.sections).flatMap(s=>s.problems);
function persist(){try{localStorage.setItem('math285-progress-v1',JSON.stringify(saved))}catch{storageOK=false}updateProgress()}
function updateProgress(){const total=allProblems().length,done=allProblems().filter(p=>saved[p.id]?.done).length;$('#progress-bar').style.width=100*done/total+'%';$('#progress-text').textContent=storageOK?`${done} / ${total} marked confident`:'Browser storage unavailable; progress lasts this session.'}
function math(){renderMathInElement($('#main'),{delimiters:[{left:'\\(',right:'\\)',display:false},{left:'\\[',right:'\\]',display:true}],throwOnError:false,strict:'ignore'})}
const linkPage=(page,label)=>`<a class="text-link" href="textbook.pdf#page=${page}" target="_blank" rel="noopener">${esc(label)} ↗</a>`;
function title(eyebrow,h1,description){return `<div class="intro"><div class="eyebrow">${eyebrow}</div><h1>${h1}</h1><p>${description}</p></div>`}
function art(){let segments='';for(let x=20;x<450;x+=26)for(let y=18;y<290;y+=25){let yy=(150-y)/52,slope=1-yy*yy,dy=Math.max(-9,Math.min(9,-slope*6));segments+=`<path d="M${x-7},${y-dy}l14,${2*dy}"/>`};return `<div class="hero-art" aria-label="Illustration of a differential equation slope field"><svg viewBox="0 0 465 300" role="img"><title>Slope field and solution curves</title><g stroke="#93ad8b" stroke-width="1.2" opacity=".55">${segments}</g><path d="M0 214 C55 214 95 210 132 182 S190 108 240 102 S350 100 465 100" stroke="#285b4b" fill="none" stroke-width="3"/><path d="M0 175 C70 170 110 133 150 110 S270 99 465 99" stroke="#719467" fill="none" stroke-width="2"/><path d="M0 241 C150 238 220 230 260 200 S318 122 375 107 S430 101 465 100" stroke="#b68647" fill="none" stroke-width="2"/><circle cx="240" cy="102" r="5" fill="#285b4b"/><text x="270" y="57" font-family="Georgia" font-style="italic" font-size="22" fill="#285b4b">y′ = f(t, y)</text></svg><div class="art-label">FROM LOCAL SLOPES TO GLOBAL BEHAVIOR</div></div>`}
function examCard(e){const count=e.keys.reduce((a,k)=>a+data.sections[k].problems.length,0);return `<a href="#exam/${e.id}" class="card exam-card ${e.id==='m2'?'current':''}"><div class="eyebrow">${date(e.date)} · 2026</div><span class="badge">${e.id==='m2'?'NEXT MIDTERM':'EXAM SCOPE'}</span><h3>${e.title}</h3><p class="muted">${e.scope}</p><div class="card-bottom"><span>${count} worked problems</span><span>Review →</span></div></a>`}
function home(){const total=allProblems().length;$('#main').innerHTML=`<section class="hero"><div><div class="eyebrow">YOUR FALL 2026 STUDY COMPANION</div><h1>Make sense of<br>differential equations.</h1><p>A clear path through Math 285. Understand why the methods work, explain the ideas in your own words, and build fluency through guided practice before each midterm.</p><div class="hero-actions"><a href="#exam/m2" class="button">Prepare for Midterm 2 →</a><a href="#lectures" class="button secondary">Explore lectures</a></div></div>${art()}</section><div class="stats"><div><b>40</b><small>Scheduled lectures</small></div><div><b>3</b><small>Midterm study tracks</small></div><div><b>${total}</b><small>Worked practice problems</small></div><div><b>${Object.keys(data.exerciseIndex).length}</b><small>Source exercise sets linked</small></div></div><div class="section-head"><h2>Study with the exam in mind.</h2><a href="#exams">See all exam scopes →</a></div><div class="cards">${data.exams.map(examCard).join('')}</div><div class="two-col"><section class="card"><div class="eyebrow">ON YOUR CALENDAR · OCTOBER 12</div><h2 style="margin-top:16px">The linear algebra bridge.</h2><p class="muted">Lecture 20 starts four lectures on §8.2. Build the matrix skills you’ll use in systems of ODEs.</p><a class="continue-row" href="#lecture/20"><span class="lecture-number">20</span><div><h3>Linear algebra toolkit</h3><p>October 12 · Section 8.2 · determinants & eigenpairs</p></div><span>→</span></a><p class="count-line" style="margin-top:15px">§8.2 is not explicitly listed in the Midterm 2 scope.</p></section><section class="card study-loop"><div class="eyebrow">A BETTER PRACTICE ROUTINE</div><h2 style="margin-top:16px">Understand. Explain. Apply.</h2><ol><li>Read the concept lesson and its small worked example.</li><li>Answer the reasoning questions in your own words.</li><li>Solve calculations; use a hint before revealing the answer.</li><li>Verify the result and revisit anything you cannot explain.</li></ol><p class="count-line">Progress and scratch work stay in this browser.</p></section></div>`}
const groups=[['all','All lectures'],['m1','Midterm 1'],['m2','Midterm 2'],['toolkit','Linear algebra'],['m3','Midterm 3'],['pde','PDEs'],['tbd','TBD']];
function lectures(){const current=new URLSearchParams(location.hash.split('?')[1]||'').get('group')||'all';$('#main').innerHTML=title('THE COURSE, IN ORDER','Your lecture roadmap.','Follow the exact Fall 2026 sequence. Exam grouping follows the stated chapter coverage, even when lecture dates overlap the next exam.')+`<div class="chips">${groups.map(([g,l])=>`<button class="chip ${g===current?'selected':''}" data-group="${g}">${l}</button>`).join('')}</div><div class="lecture-list">${data.lectures.filter(l=>current==='all'||l.group===current).map(l=>{const s=data.sections[l.section];let row=`<a href="#lecture/${l.number}" class="lecture-row"><span class="lecture-index">${String(l.number).padStart(2,'0')}</span><span class="lecture-date">${date(l.date)}</span><div><h3>${s?esc(s.title):'Topic to be determined'}</h3><p>${s?'§'+s.id:'TBD'} · ${s?s.problems.length+' worked problems':'No topic supplied'}</p></div><span class="badge">${groups.find(g=>g[0]===l.group)?.[1]||'TBD'}</span></a>`;if(l.number===13)row+=`<div class="event">SEP 25 · MIDTERM 1 — Chapter 1. A1–C1 have no lecture; D1 covers §2.6 early.</div>`;if(l.number===24)row+=`<div class="event">OCT 23 · MIDTERM 2 — Chapters 2–3. No lecture.</div>`;if(l.number===38)row+=`<div class="event">DEC 04 · MIDTERM 3 — Chapters 4–6. No lecture.</div>`;return row}).join('')}</div><div class="note">September 30: D1 has no lecture and all sections return to the same schedule. Repeated sections share one practice bank; the calendar does not assign separate subtopics to each repeated lecture.</div>`;$('#main').querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{location.hash='lectures?group='+b.dataset.group})}
function problemHTML(p,index){return `<article class="problem" data-kind="${p.kind==='concept'?'concept':'calculation'}" id="problem-${p.id}"><div class="problem-top"><span class="problem-ref">${esc(p.ref)} · ${linkPage(p.page,'p. '+p.page)}</span><label class="mastered"><input type="checkbox" data-done="${p.id}" ${saved[p.id]?.done?'checked':''}> Mark confident</label></div><h3>${index?index+'. ':''}${esc(p.title)} <span class="problem-type">${p.kind==='concept'?'REASONING':'CALCULATION'}</span></h3><div class="prompt">${esc(p.prompt)}</div><details class="scratch"><summary>Write an attempt · saved locally</summary><textarea data-notes="${p.id}" aria-label="Your attempt for ${esc(p.title)}" placeholder="Your reasoning, calculations, or questions…">${esc(saved[p.id]?.notes||'')}</textarea></details><div class="problem-controls"><button class="hint-button" data-hint="${p.id}">Show hint 1 of ${p.hints.length}</button></div><div data-hints="${p.id}"></div><details class="solution"><summary>${p.kind==='concept'?'Reveal conceptual explanation':'Reveal worked solution'}</summary>${p.kind==='concept'?`<div class="concept-answer">${p.steps.map(s=>`<p>${esc(s)}</p>`).join('')}</div>`:`<ol>${p.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="answer">\\[${esc(p.answer)}\\]</div>`}<div class="check"><b>Check & interpretation:</b> ${esc(p.check)}</div></details></article>`}
function wireProblems(){const byId=Object.fromEntries(allProblems().map(p=>[p.id,p]));$('#main').querySelectorAll('[data-done]').forEach(c=>c.onchange=()=>{saved[c.dataset.done]={...saved[c.dataset.done],done:c.checked};persist()});$('#main').querySelectorAll('[data-notes]').forEach(t=>t.oninput=()=>{saved[t.dataset.notes]={...saved[t.dataset.notes],notes:t.value};persist()});$('#main').querySelectorAll('[data-hint]').forEach(b=>{let n=0;b.onclick=()=>{const p=byId[b.dataset.hint],h=document.createElement('div');h.className='hint';h.textContent=`Hint ${n+1}: ${p.hints[n++]}`;$('#main').querySelector(`[data-hints="${p.id}"]`).append(h);if(n===p.hints.length){b.disabled=true;b.textContent='All hints revealed'}else b.textContent=`Show hint ${n+1} of ${p.hints.length}`;math()}})}
function sourceSet(s){return `<section class="card"><h3>Continue in the course notes</h3><p class="count-line">${s.sourceExercises.length?'Original exercise sets below may contain additional subparts beyond this site’s selected worked practice.':'This section has no separately numbered exercise set in the supplied notes. The site includes supplemental practice based on the section.'}</p><div class="source-links">${s.sourceExercises.map(e=>`<a href="textbook.pdf#page=${e.page}" target="_blank" rel="noopener">Exercise ${e.ref} · p. ${e.page} ↗</a>`).join('')}</div></section>`}

function lessonHTML(s){const l=s.lesson;if(!l)return '';return '<section class="concept-lesson" aria-labelledby="concept-heading"><div class="section-head"><h2 id="concept-heading">Understand the idea first.</h2><span class="badge">CONCEPT FIRST</span></div><div class="big-idea"><div class="eyebrow">THE CENTRAL IDEA</div><p>'+esc(l.bigIdea)+'</p></div><div class="lesson-prose">'+l.understand.map(p=>'<p>'+esc(p)+'</p>').join('')+'</div><div class="why-box"><h3>Why the method works</h3><p>'+esc(l.why)+'</p></div><div class="lesson-example"><div class="eyebrow">A SMALL EXAMPLE, WITH THE REASONING</div><h3>'+esc(l.example.prompt)+'</h3><p>'+esc(l.example.explanation)+'</p><div class="formula">\\['+esc(l.example.math)+'\\]</div></div><div class="lesson-method"><h3>How to approach a problem</h3><ol>'+l.method.map(p=>'<li>'+esc(p)+'</li>').join('')+'</ol><p class="lesson-connection"><strong>Connect it:</strong> '+esc(l.connection)+'</p></div></section>'}
function wirePracticeModes(){document.querySelectorAll('[data-practice-mode]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-practice-mode]').forEach(x=>x.classList.toggle('selected',x===b));document.querySelectorAll('.problem').forEach(p=>{p.hidden=b.dataset.practiceMode!=='all'&&p.dataset.kind!==b.dataset.practiceMode});})}

function topic(key,lecture){const s=data.sections[key];if(!s){$('#main').innerHTML=title('LECTURE '+lecture.number,'Topic to be determined.','December 9 is listed as “tbd” in the course calendar. No textbook section or exam scope was assigned.')+`<a href="#lectures" class="button">Back to roadmap</a>`;return}const dates=data.lectures.filter(l=>l.section===key);const selected=lecture?`Lecture ${String(lecture.number).padStart(2,'0')} · ${date(lecture.date)}`:'Section '+key;$('#main').innerHTML=`<div class="crumb"><a href="#lectures">Lecture roadmap</a> / ${esc(selected)}</div><div class="topic-top"><div><div class="eyebrow">${esc(selected)} · §${key}</div><h1>${esc(s.title)}</h1></div><a href="textbook.pdf#page=${s.page}" class="button secondary" target="_blank" rel="noopener">Read section · p. ${s.page} ↗</a></div><p class="count-line">Scheduled ${dates.map(l=>`<a class="text-link" href="#lecture/${l.number}">Lecture ${l.number} · ${date(l.date)}</a>`).join(' / ')}</p>${dates.length>1?'<div class="note">The calendar repeats this section. Each lecture uses the same section guide and practice bank; subtopics are not assigned separately in the source calendar.</div>':''}${lessonHTML(s)}<div class="topic-grid"><section class="card"><div class="eyebrow">WHAT TO KNOW</div><ul class="goals">${s.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><div class="formula">\\[${esc(s.formula)}\\]</div></section><section class="card"><div class="eyebrow">WATCH FOR THIS</div><h3 style="margin-top:12px">A common mistake</h3><p class="muted">${esc(s.trap)}</p><p class="count-line">After solving, verify the equation, initial data, domain, and units when applicable.</p></section></div><div class="section-head"><h2 id="practice-heading">Explain it. Then solve it.</h2><span class="count-line">${s.problems.length} worked problems</span></div><p class="practice-intro">Start with the reasoning questions. Then apply the method to multiple calculation problems, using hints before opening a solution.</p><div class="chips" aria-label="Practice type"><button class="chip selected" data-practice-mode="all">All practice</button><button class="chip" data-practice-mode="concept">Conceptual reasoning</button><button class="chip" data-practice-mode="calculation">Calculations</button></div>${s.problems.map((p,i)=>problemHTML(p,i+1)).join('')}${sourceSet(s)}${lecture?`<div class="row-actions">${lecture.number>1?`<a class="button secondary" href="#lecture/${lecture.number-1}">← Lecture ${lecture.number-1}</a>`:'<span></span>'}${lecture.number<40?`<a class="button" href="#lecture/${lecture.number+1}">Lecture ${lecture.number+1} →</a>`:''}</div>`:''}`;wireProblems();wirePracticeModes()}
function practice(){const search=new URLSearchParams(location.hash.split('?')[1]||'');const query=search.get('q')||'',group=search.get('group')||'all',unfinished=search.get('unfinished')==='1';let entries=Object.values(data.sections).filter(s=>{const g=data.lectures.find(l=>l.section===s.id)?.group;return (group==='all'||group===g)&&(!query||(s.id+' '+s.title+' '+s.lesson.bigIdea+' '+s.lesson.understand.join(' ')+' '+s.goals.join(' ')+' '+s.problems.map(p=>p.title+' '+p.prompt+' '+p.ref).join(' ')).toLowerCase().includes(query.toLowerCase()))&&(!unfinished||s.problems.some(p=>!saved[p.id]?.done))});$('#main').innerHTML=title('BUILD FLUENCY, ONE PROBLEM AT A TIME','The practice library.','Browse by topic, search for a method, or focus on problems you haven’t marked confident. Every worked problem has hints, a clear solution, and a verification step.')+`<form class="toolbar" id="search-form"><input name="q" type="search" value="${esc(query)}" placeholder="Search topics, methods, or exercise numbers…" aria-label="Search practice"><select name="group" aria-label="Filter by exam scope">${groups.filter(g=>g[0]!=='tbd').map(([g,l])=>`<option value="${g}" ${g===group?'selected':''}>${l}</option>`).join('')}</select><label><input name="unfinished" type="checkbox" value="1" ${unfinished?'checked':''}> Needs practice</label><button class="button">Search</button></form><p class="count-line">${entries.length} topics · ${entries.reduce((a,s)=>a+s.problems.length,0)} worked problems${unfinished?' (topics with unfinished practice)':''}</p><div class="cards">${entries.map(s=>`<a href="#topic/${s.id}" class="card practice-card"><div class="eyebrow">SECTION ${s.id}</div><h3>${esc(s.title)}</h3><small>${s.problems.length} problems · ${s.problems.filter(p=>saved[p.id]?.done).length} marked confident →</small></a>`).join('')}</div>${entries.length?'':'<div class="empty">No topics match. Try a broader search or a different scope.</div>'}`;$('#search-form').onsubmit=e=>{e.preventDefault();location.hash='practice?'+new URLSearchParams(new FormData(e.target)).toString()}}
function exams(){ $('#main').innerHTML=title('PREPARE TO THE STATED SCOPE','Three midterms. Clear boundaries.','These tracks follow the chapters named in your course calendar. Use each section’s guide for methods, then test yourself with a mixed review set.')+`<div class="cards" style="margin-top:30px">${data.exams.map(examCard).join('')}</div><div class="note">Midterm 2 is Chapters 2–3, even though §8.2 and §§4.1–4.2 are taught before October 23. Midterm 3 is Chapters 4–6, even though §7.1 and §7.2 are taught before December 4. Linear algebra and PDEs have separate tracks; no final exam date or scope is supplied.</div>`}
function exam(id){const e=data.exams.find(e=>e.id===id);if(!e){location.hash='exams';return}const ps=e.keys.flatMap(k=>data.sections[k].problems),done=ps.filter(p=>saved[p.id]?.done).length;$('#main').innerHTML=`<div class="crumb"><a href="#exams">Midterm preparation</a> / ${e.title}</div><div class="eyebrow">${date(e.date)} · 2026</div><div class="exam-title"><h1>${e.title}</h1><button class="button" id="mixed">New mixed review ↻</button></div><p class="exam-meta">${e.scope} · ${ps.length} worked problems · ${done} marked confident</p><div class="note">Work through the topic guides first. The mixed review below selects one problem from each topic in this exam scope. Reveal hints and solutions only after an attempt.</div><div class="cards">${e.keys.map(k=>{const s=data.sections[k];return `<a href="#topic/${k}" class="card practice-card"><div class="eyebrow">§${k}</div><h3>${esc(s.title)}</h3><small>${s.problems.length} problems →</small></a>`}).join('')}</div><section style="margin-top:35px"><div class="section-head"><h2>Mixed review</h2><span class="count-line">One problem per topic · no timer</span></div><div id="mixed-problems"></div></section>`;const draw=()=>{$('#mixed-problems').innerHTML=e.keys.map(k=>{const ps=data.sections[k].problems;return problemHTML(ps[Math.floor(Math.random()*ps.length)])}).join('');wireProblems();math()};$('#mixed').onclick=draw;draw()}
function track(group){const keys=Object.keys(data.sections).filter(k=>group==='toolkit'?k==='8.2':k.startsWith('7.'));$('#main').innerHTML=title(group==='toolkit'?'THE BRIDGE TO SYSTEMS':'BEYOND THE LISTED MIDTERMS',group==='toolkit'?'Your linear algebra toolkit.':'PDEs & final topics.',group==='toolkit'?'Lectures 20–23 cover §8.2: matrices, systems, determinants, eigenvalues, and eigenvectors. The stated Midterm 2 scope is Chapters 2–3, so this toolkit is kept separate.':'The calendar includes heat and wave equations before Midterm 3, and Laplace’s equation afterward. The stated Midterm 3 scope is Chapters 4–6; final exam coverage is not supplied.')+`<div class="cards" style="margin-top:25px">${keys.map(k=>`<a href="#topic/${k}" class="card practice-card"><div class="eyebrow">§${k}</div><h3>${esc(data.sections[k].title)}</h3><small>${data.sections[k].problems.length} worked problems →</small></a>`).join('')}</div><div class="note">${group==='toolkit'?'Use this track alongside the systems material in Chapter 4.':'Lecture 39’s “Laplace eq” is mapped to textbook §7.3 (Laplace’s PDE), not §2.8 (the Laplace transform). Lecture 40 remains TBD.'}</div>`}
function sources(){ $('#main').innerHTML=title('TRANSPARENT SOURCES','Built around your course.','Your supplied notes provide the mathematics and practice exercises; your calendar determines lecture order and midterm scope.')+`<div class="card"><h3>Course notes</h3><p>Jared C. Bronski and Aldo J. Manfroi, <i>Differential Equations</i>, University of Illinois Mathematics, first printing April 2026. Supplied file: Math_285_Notes_1_5.pdf, 213 pages. The PDF includes Chapters 1–8 and an answer chapter.</p><p>${linkPage(5,'Table of contents')} · ${linkPage(193,'Original problem solutions')}</p><p class="count-line">Notes copyright © 2026 Jared C. Bronski and Aldo J. Manfroi, licensed under Apache License 2.0 as stated on page 4. The supplied PDF is preserved unchanged; site explanations and worked solutions are newly written. <a class="text-link" href="LICENSE.txt" target="_blank">License</a>.</p></div><div class="card" style="margin-top:18px"><h3>Lecture schedule</h3><p><a href="calendar.txt" target="_blank" class="text-link">Calendar Fa2026.txt ↗</a> supplies 40 lectures and three chapter-based midterm scopes. It includes the A1–C1 / D1 scheduling exceptions, the repeated sections, and the final TBD lecture.</p></div><div class="card" style="margin-top:18px"><h3>What this guide covers</h3><p>${allProblems().length} worked practice problems, including conceptual reasoning, cover all ${Object.keys(data.sections).length} scheduled topic groups. Every topic starts with intuition, why the method works, an explanatory example, and a problem-solving approach. Each has at least four practice problems. Numbered problems cite the source exercise and PDF page; supplemental practice is explicitly labeled. All ${Object.keys(data.exerciseIndex).length} original numbered exercise sets are indexed below, including extra material not explicitly assigned in the calendar.</p><p>The guide does not provide worked solutions to every subpart in the textbook. Use the linked original sets for further practice and the notes’ answer chapter where available. Repeated lecture dates share a section bank because the calendar does not assign different subtopics.</p><p>Solutions are derived for this guide. Where source typos or incompatible endpoint data affect a result, the check explains the correction or interpretation.</p><p class="count-line">Progress and attempts are stored locally in this browser. They do not sync to another device.</p></div><h2 style="margin-top:30px">Complete source exercise index</h2><div class="source-links">${Object.entries(data.exerciseIndex).map(([ref,page])=>`<a href="textbook.pdf#page=${page}" target="_blank" rel="noopener">${ref} · p. ${page} ↗</a>`).join('')}</div>`}
function route(){const raw=location.hash.slice(1)||'home',path=raw.split('?')[0],parts=path.split('/');$('#sidebar').querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===parts[0]||(parts[0]==='exam'&&a.dataset.nav==='exams')||(parts[0]==='lecture'&&a.dataset.nav==='lectures')||(parts[0]==='topic'&&a.dataset.nav==='practice')));document.body.classList.remove('sidebar-open');$('#menu').setAttribute('aria-expanded','false');if(parts[0]==='home')home();else if(parts[0]==='lectures')lectures();else if(parts[0]==='lecture'){const l=data.lectures.find(l=>l.number===Number(parts[1]));if(l)topic(l.section,l);else home()}else if(parts[0]==='topic'){if(data.sections[parts[1]])topic(parts[1]);else home()}else if(parts[0]==='practice')practice();else if(parts[0]==='exams')exams();else if(parts[0]==='exam')exam(parts[1]);else if(['toolkit','pde'].includes(parts[0]))track(parts[0]);else if(parts[0]==='sources')sources();else home();math();window.scrollTo(0,0);document.title=`Math 285 · ${$('#main h1')?.textContent||'Study guide'}`}
$('#menu').onclick=()=>{const on=document.body.classList.toggle('sidebar-open');$('#menu').setAttribute('aria-expanded',String(on))};
fetch('content.json').then(r=>{if(!r.ok)throw Error('Content unavailable');return r.json()}).then(d=>{data=d;$('#problem-count').textContent=allProblems().length;updateProgress();route();window.addEventListener('hashchange',route)}).catch(e=>{$('#main').innerHTML=`<h1>Could not load the guide.</h1><p>Reload this page. If the problem persists, the site content may be temporarily unavailable.</p><p>${esc(e.message)}</p>`});
